map(fn) { return new Plan(source, {previous: tail, kind: "map", fn}); }
filter(fn) { return new Plan(source, {previous: tail, kind: "filter", fn}); }
terminal(target, collect) {
 const ops = compileIteratively(tail); const output=[]; let ordinal=0;
 sourceLoop: for (const original of source) { let value=original;
  for (const op of ops) { if (op.kind==="filter") { if (!op.fn(value)) continue sourceLoop; }
   else for (const fn of op.mapRun) value=fn(value); }
  if (!collect && Object.is(value,target)) return ordinal;
  if (collect) output.push(value); ordinal++;
 } return collect ? output : -1;
}

